"""Expression evaluation for minisql.

The public entry point is :func:`evaluate`, which walks an AST expression and
returns a Python value (``None`` for SQL NULL, ``bool``, ``int``, ``float`` or
``str``).  All semantic errors are reported as :class:`minisql.errors.QueryError`.

Values are restricted to ``None``, ``bool``, ``int``, ``float`` and ``str``.
Because ``bool`` is a subclass of ``int`` in Python, the type helpers below
deliberately treat booleans as a separate kind.
"""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

from .ast import (
    AGGREGATE_NAMES,
    Between,
    Binary,
    Column,
    FuncCall,
    InList,
    IsNull,
    Like,
    Literal,
    Star,
    Unary,
    contains_aggregate,
    is_aggregate,
)
from .errors import QueryError

__all__ = ["evaluate"]


# ---------------------------------------------------------------------------
# Value-kind helpers
# ---------------------------------------------------------------------------


def _is_bool(value):
    return isinstance(value, bool)


def _is_int(value):
    """True for integers, but not booleans (which subclass int)."""
    return isinstance(value, int) and not isinstance(value, bool)


def _is_number(value):
    """True for ints and floats, but not booleans."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _kind(value):
    if value is None:
        return "null"
    if _is_bool(value):
        return "boolean"
    if _is_number(value):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


# ---------------------------------------------------------------------------
# Comparison
# ---------------------------------------------------------------------------


def _compare_non_null(left, right):
    """Compare two non-NULL values, returning -1, 0 or 1.

    Raises QueryError when the two values are of incomparable kinds.
    """
    if _is_number(left) and _is_number(right):
        pass
    elif _is_bool(left) and _is_bool(right):
        pass
    elif isinstance(left, str) and isinstance(right, str):
        pass
    else:
        raise QueryError(
            "cannot compare {} with {}".format(_kind(left), _kind(right))
        )

    if left < right:
        return -1
    if left > right:
        return 1
    return 0


def _compare(left, right):
    """Compare two values, returning -1, 0, 1, or None when either is NULL."""
    if left is None or right is None:
        return None
    return _compare_non_null(left, right)


# ---------------------------------------------------------------------------
# Three-valued logic
# ---------------------------------------------------------------------------


def _check_logical(value, op):
    if value is not None and not isinstance(value, bool):
        raise QueryError("{} requires boolean operands".format(op))


def _and3(left, right):
    """Three-valued AND over already validated boolean/NULL operands."""
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _or3(left, right):
    """Three-valued OR over already validated boolean/NULL operands."""
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


# ---------------------------------------------------------------------------
# Arithmetic and text
# ---------------------------------------------------------------------------


def _arithmetic(op, left, right):
    if not (_is_number(left) and _is_number(right)):
        raise QueryError(
            "operator {} requires numeric operands, got {} and {}".format(
                op, _kind(left), _kind(right)
            )
        )

    if op == "/":
        if right == 0:
            return None
        return left / right

    if op == "+":
        result = left + right
    elif op == "-":
        result = left - right
    elif op == "*":
        result = left * right
    else:  # pragma: no cover - guarded by the caller
        raise QueryError("unknown arithmetic operator: {}".format(op))

    if _is_int(left) and _is_int(right):
        return result
    return float(result)


def _to_text(value):
    if isinstance(value, str):
        return value
    return str(value)


# ---------------------------------------------------------------------------
# LIKE
# ---------------------------------------------------------------------------


def _like_match(value, pattern):
    """Whole-string LIKE matching with ``%`` and ``_`` wildcards."""
    length = len(value)
    plen = len(pattern)

    # previous[j] means pattern[:j] matches value[:i] for the current i.
    previous = [False] * (plen + 1)
    previous[0] = True
    for j in range(1, plen + 1):
        if pattern[j - 1] == "%":
            previous[j] = previous[j - 1]

    for i in range(1, length + 1):
        current = [False] * (plen + 1)
        char = value[i - 1]
        for j in range(1, plen + 1):
            token = pattern[j - 1]
            if token == "%":
                current[j] = current[j - 1] or previous[j]
            elif token == "_":
                current[j] = previous[j - 1]
            else:
                current[j] = previous[j - 1] and char == token
        previous = current

    return previous[plen]


# ---------------------------------------------------------------------------
# Scalar functions
# ---------------------------------------------------------------------------


def _round_to_int(value):
    if _is_int(value):
        return value
    try:
        with localcontext() as context:
            context.prec = 100
            rounded = Decimal(str(value)).quantize(
                Decimal(1), rounding=ROUND_HALF_UP
            )
        return int(rounded)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("ROUND: value out of range")


def _round_to_places(value, places):
    try:
        with localcontext() as context:
            context.prec = 100
            exponent = Decimal(1).scaleb(-places)
            rounded = Decimal(str(value)).quantize(
                exponent, rounding=ROUND_HALF_UP
            )
        return float(rounded)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("ROUND: value out of range")


def _eval_scalar(node, row, group):
    name = node.name.upper()
    args = node.args

    if node.star:
        raise QueryError("function {} does not accept '*'".format(name))

    if name in ("LOWER", "UPPER", "LENGTH"):
        if len(args) != 1:
            raise QueryError("{} takes exactly one argument".format(name))
        value = evaluate(args[0], row, group)
        if value is None:
            return None
        if not isinstance(value, str):
            raise QueryError("{} requires a string argument".format(name))
        if name == "LOWER":
            return value.lower()
        if name == "UPPER":
            return value.upper()
        return len(value)

    if name == "ABS":
        if len(args) != 1:
            raise QueryError("ABS takes exactly one argument")
        value = evaluate(args[0], row, group)
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("ABS requires a numeric argument")
        return abs(value)

    if name == "ROUND":
        if len(args) not in (1, 2):
            raise QueryError("ROUND takes one or two arguments")
        value = evaluate(args[0], row, group)
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("ROUND requires a numeric argument")
        if len(args) == 1:
            return _round_to_int(value)
        places = evaluate(args[1], row, group)
        if places is None:
            return None
        if not _is_int(places):
            raise QueryError("ROUND requires an integer number of places")
        return _round_to_places(value, places)

    if name == "COALESCE":
        if not args:
            raise QueryError("COALESCE requires at least one argument")
        for arg in args:
            value = evaluate(arg, row, group)
            if value is not None:
                return value
        return None

    raise QueryError("unknown function: {}".format(node.name))


# ---------------------------------------------------------------------------
# Aggregates
# ---------------------------------------------------------------------------


def _check_not_nested(node, name):
    if contains_aggregate(node):
        raise QueryError(
            "aggregate function {} cannot be nested".format(name)
        )


def _eval_aggregate(node, row, group):
    name = node.name.upper()

    if group is None:
        raise QueryError(
            "aggregate function {} requires a grouped context".format(name)
        )

    args = node.args

    if name == "COUNT":
        if node.star:
            if args:
                raise QueryError("COUNT(*) does not take arguments")
            return len(group)
        if len(args) != 1:
            raise QueryError("COUNT takes exactly one argument or '*'")
        arg = args[0]
        _check_not_nested(arg, name)
        count = 0
        for group_row in group:
            if evaluate(arg, group_row, None) is not None:
                count += 1
        return count

    if node.star:
        raise QueryError("{} does not accept '*'".format(name))
    if len(args) != 1:
        raise QueryError("{} takes exactly one argument".format(name))

    arg = args[0]
    _check_not_nested(arg, name)

    values = []
    for group_row in group:
        value = evaluate(arg, group_row, None)
        if value is not None:
            values.append(value)

    if not values:
        return None

    if name == "SUM":
        total = 0
        has_float = False
        for value in values:
            if not _is_number(value):
                raise QueryError("SUM requires numeric values")
            if isinstance(value, float):
                has_float = True
            total = total + value
        return float(total) if has_float else total

    if name == "AVG":
        total = 0
        for value in values:
            if not _is_number(value):
                raise QueryError("AVG requires numeric values")
            total = total + value
        return total / len(values)

    if name in ("MIN", "MAX"):
        best = values[0]
        for value in values[1:]:
            comparison = _compare_non_null(best, value)
            if name == "MIN":
                if comparison > 0:
                    best = value
            else:
                if comparison < 0:
                    best = value
        return best

    # Unreachable: is_aggregate only recognises the names above.
    raise QueryError("unknown aggregate function: {}".format(node.name))


# ---------------------------------------------------------------------------
# Columns
# ---------------------------------------------------------------------------


def _column_value(name, row):
    if name in row:
        return row[name]

    lowered = name.lower()
    if lowered in row:
        return row[lowered]

    # Be tolerant of callers that did not normalise the header names.
    for key, value in row.items():
        if isinstance(key, str) and key.lower() == lowered:
            return value

    raise QueryError("unknown column: {}".format(name))


# ---------------------------------------------------------------------------
# Node evaluation
# ---------------------------------------------------------------------------


def _eval_unary(node, row, group):
    op = node.op.upper()
    value = evaluate(node.operand, row, group)

    if op == "NOT":
        if value is None:
            return None
        if not isinstance(value, bool):
            raise QueryError("NOT requires a boolean operand")
        return not value

    if op == "-":
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("unary - requires a numeric operand")
        return -value

    raise QueryError("unknown unary operator: {}".format(node.op))


def _eval_binary(node, row, group):
    op = node.op.upper()

    left = evaluate(node.left, row, group)
    right = evaluate(node.right, row, group)

    if op == "AND":
        _check_logical(left, "AND")
        _check_logical(right, "AND")
        return _and3(left, right)

    if op == "OR":
        _check_logical(left, "OR")
        _check_logical(right, "OR")
        return _or3(left, right)

    if op == "||":
        if left is None or right is None:
            return None
        return _to_text(left) + _to_text(right)

    if op in ("+", "-", "*", "/"):
        if left is None or right is None:
            return None
        return _arithmetic(op, left, right)

    if op in ("=", "!=", "<>", "<", "<=", ">", ">="):
        comparison = _compare(left, right)
        if comparison is None:
            return None
        if op == "=":
            return comparison == 0
        if op in ("!=", "<>"):
            return comparison != 0
        if op == "<":
            return comparison < 0
        if op == "<=":
            return comparison <= 0
        if op == ">":
            return comparison > 0
        return comparison >= 0

    raise QueryError("unknown operator: {}".format(node.op))


def _eval_in(node, row, group):
    value = evaluate(node.operand, row, group)
    items = [evaluate(item, row, group) for item in node.items]

    found = False
    any_null = value is None

    for item in items:
        comparison = _compare(value, item)
        if comparison is None:
            any_null = True
        elif comparison == 0:
            found = True
            break

    if found:
        result = True
    elif any_null:
        result = None
    else:
        result = False

    if node.negated and result is not None:
        result = not result
    return result


def _eval_between(node, row, group):
    value = evaluate(node.operand, row, group)
    low = evaluate(node.low, row, group)
    high = evaluate(node.high, row, group)

    low_comparison = _compare(low, value)
    high_comparison = _compare(value, high)

    low_ok = None if low_comparison is None else low_comparison <= 0
    high_ok = None if high_comparison is None else high_comparison <= 0

    result = _and3(low_ok, high_ok)
    if node.negated and result is not None:
        result = not result
    return result


def _eval_like(node, row, group):
    value = evaluate(node.operand, row, group)
    pattern = evaluate(node.pattern, row, group)

    if value is None or pattern is None:
        return None
    if not isinstance(value, str) or not isinstance(pattern, str):
        raise QueryError("LIKE requires string operands")

    result = _like_match(value, pattern)
    if node.negated:
        result = not result
    return result


def evaluate(node, row, group=None):
    """Evaluate an AST expression.

    row: dict mapping lower-case CSV column names to Python values
         (None, bool, int, float, str). For an empty group this may be {}.
    group: None for a non-grouped/row context, or a list of row dicts for a
           grouped context. Aggregate calls evaluate over this list.
    """
    if node is None:
        raise QueryError("missing expression")

    if isinstance(node, Literal):
        return node.value

    if isinstance(node, Column):
        return _column_value(node.name, row)

    if isinstance(node, Star):
        raise QueryError("'*' is not valid in this expression")

    if isinstance(node, Unary):
        return _eval_unary(node, row, group)

    if isinstance(node, Binary):
        return _eval_binary(node, row, group)

    if isinstance(node, IsNull):
        value = evaluate(node.operand, row, group)
        result = value is None
        return (not result) if node.negated else result

    if isinstance(node, InList):
        return _eval_in(node, row, group)

    if isinstance(node, Between):
        return _eval_between(node, row, group)

    if isinstance(node, Like):
        return _eval_like(node, row, group)

    if isinstance(node, FuncCall):
        if is_aggregate(node):
            return _eval_aggregate(node, row, group)
        return _eval_scalar(node, row, group)

    raise QueryError("unsupported expression: {}".format(type(node).__name__))
